    # Interpretation/quality belongs to chapter 1, before the chapter 2 demonstration.
    output = p[:5]+[process]+[legal]+p[6:12]+([gap] if gap else [])+[p[12],p[13]]
    output += p[14:23]+p[24:27]+[p[23],data_demo,p[27],references]
